package awsschema

import "github.com/bellu/bellucode/services/bellud/internal/graph/schema"

// relations lists the 59 aws relation types of the design table
// (.kiro/specs/aws-relationship-registry/design.md, section 3.1). Each
// description is the row's Direction_Rule justification; table_test.go fails
// when a name, direction, confidence, or description differs from the table.
func relations() []schema.RelationDeclaration {
	return []schema.RelationDeclaration{
		{Name: "aws_member_of", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The account is contained in the organization; an organization change impacts the account.",
			From: []string{"aws_account"}, To: []string{"organizations:organization"}},
		{Name: "aws_child_of", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The child sits under its parent in the hierarchy; a parent change impacts the child.",
			From: []string{"aws_account", "organizations:ou"}, To: []string{"organizations:ou", "organizations:root"}},
		{Name: "aws_scp_attached", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The target depends on the SCP that governs it; a change to the SCP impacts the target. Not an identity policy attachment.",
			From: []string{"aws_account", "organizations:ou", "organizations:root"}, To: []string{"organizations:scp"}},
		{Name: "aws_in_vpc", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The resource is contained in the VPC. Containment alone gives no capability.",
			From: []string{"ec2:subnet", "ec2:security-group", "ec2:route-table", "ec2:network-acl", "ec2:vpc-endpoint"}, To: []string{"ec2:vpc"}},
		{Name: "aws_in_subnet", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The ENI is contained in the subnet.",
			From: []string{"ec2:eni"}, To: []string{"ec2:subnet"}},
		{Name: "aws_has_eni", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The workload depends on its ENI for connectivity; ENI failure impacts the workload. Reach through the ENI is walked by netreach.",
			From: []string{"ec2:instance", "lambda:function", "ecs:task", "elbv2:load-balancer", "ec2:nat-gateway", "ec2:vpc-endpoint"}, To: []string{"ec2:eni"}},
		{Name: "aws_member_of_sg", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The ENI depends on its security group for filtering; a rule change impacts the ENI.",
			From: []string{"ec2:eni"}, To: []string{"ec2:security-group"}},
		{Name: "aws_routes_to", Direction: schema.Forward, Confidence: schema.Extracted, Description: "A route gives traffic a path to its target, so the route table gives reach over the target. Evidence lists destination CIDRs.",
			From: []string{"ec2:route-table"}, To: []string{"ec2:internet-gateway", "ec2:nat-gateway", "ec2:transit-gateway", "ec2:vpc-peering", "ec2:vpc-endpoint", "ec2:eni", "ec2:vpc"}},
		{Name: "aws_route_of", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The route is contained in its route table.",
			From: []string{"ec2:route"}, To: []string{"ec2:route-table"}},
		{Name: "aws_associated_subnet", Direction: schema.Forward, Confidence: schema.Extracted, Description: "Failure or change of the table or ACL changes the subnet's routing or filtering. Direction fixed by Req 9.7.",
			From: []string{"ec2:route-table", "ec2:network-acl"}, To: []string{"ec2:subnet"}},
		{Name: "aws_attached_igw", Direction: schema.Forward, Confidence: schema.Extracted, Description: "Failure or compromise of the gateway changes the VPC's internet exposure. Not `attached_to`.",
			From: []string{"ec2:internet-gateway"}, To: []string{"ec2:vpc"}},
		{Name: "aws_nat_in_subnet", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The NAT gateway is contained in the subnet.",
			From: []string{"ec2:nat-gateway"}, To: []string{"ec2:subnet"}},
		{Name: "aws_peers_with", Direction: schema.Forward, Confidence: schema.Extracted, Description: "A peering lets the first VPC reach the second. Emitted in both directions for an active peering.",
			From: []string{"ec2:vpc"}, To: []string{"ec2:vpc"}},
		{Name: "aws_tgw_attached", Direction: schema.Forward, Confidence: schema.Extracted, Description: "An attachment gives its network reach over the gateway and the attached VPC.",
			From: []string{"ec2:tgw-attachment"}, To: []string{"ec2:transit-gateway", "ec2:vpc"}},
		{Name: "aws_lb_forwards_to", Direction: schema.Forward, Confidence: schema.Extracted, Description: "A listener sends traffic to the target group, so an attacker at the listener reaches the targets.",
			From: []string{"elbv2:listener"}, To: []string{"elbv2:target-group"}},
		{Name: "aws_lb_listener_of", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The listener belongs to its load balancer; load balancer failure impacts the listener.",
			From: []string{"elbv2:listener"}, To: []string{"elbv2:load-balancer"}},
		{Name: "aws_targets", Direction: schema.Forward, Confidence: schema.Extracted, Description: "A target group sends traffic to its registered targets.",
			From: []string{"elbv2:target-group"}, To: []string{"ec2:instance", "ec2:eni", "lambda:function"}},
		{Name: "aws_rule_of", Direction: schema.Forward, Confidence: schema.Extracted, Description: "The rule defines the group's filtering; a rule failure or compromise changes who reaches the group. Both criteria matched.",
			From: []string{"aws_sg_rule"}, To: []string{"ec2:security-group"}},
		{Name: "aws_rule_peer", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The rule depends on its peer; compromise of the peer reaches the rule's group. Impact is meaningful for ingress rules.",
			From: []string{"aws_sg_rule"}, To: []string{"aws_cidr", "ec2:security-group"}},
		{Name: "aws_assigned_to", Direction: schema.Forward, Confidence: schema.Extracted, Description: "Failure or release of the address changes the target's reachability. Not `attached_to`.",
			From: []string{"ec2:eip"}, To: []string{"ec2:eni", "ec2:instance", "ec2:nat-gateway"}},
		{Name: "aws_exposed_via", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The resource is reachable from the internet through the gateway; compromise of the internet side impacts the resource. Evidence and confidence per exposure result.",
			From: []string{"ec2:instance", "elbv2:load-balancer"}, To: []string{"ec2:internet-gateway"}},
		{Name: "aws_allows_ingress_from", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "Derived by the lens. The group allows ingress from the peer, so peer compromise reaches the group's members. The edge points at the source, so impact flows peer to group.",
			From: []string{"ec2:security-group"}, To: []string{"aws_cidr", "ec2:security-group"}, Derived: true},
		{Name: "aws_allows_egress_to", Direction: schema.Forward, Confidence: schema.Extracted, Description: "Derived by the lens. Members of the group may open connections to the peer, so compromise of a member reaches the peer.",
			From: []string{"ec2:security-group"}, To: []string{"aws_cidr", "ec2:security-group"}, Derived: true},
		{Name: "aws_uses_image", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The workload depends on its image. Joins to the core `image` kind through the digest key.",
			From: []string{"ec2:instance", "ec2:launch-template", "ecs:task", "lambda:function"}, To: []string{"ec2:image", "image"}},
		{Name: "aws_in_asg", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The instance is a member of the group.",
			From: []string{"ec2:instance"}, To: []string{"autoscaling:group"}},
		{Name: "aws_launched_from", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The resource depends on the template that defines it.",
			From: []string{"ec2:instance", "autoscaling:group"}, To: []string{"ec2:launch-template"}},
		{Name: "aws_has_instance_profile", Direction: schema.Forward, Confidence: schema.Extracted, Description: "Compromise of the instance yields the profile credentials. Both criteria matched.",
			From: []string{"ec2:instance", "ec2:launch-template"}, To: []string{"iam:instance-profile"}},
		{Name: "aws_profile_has_role", Direction: schema.Forward, Confidence: schema.Extracted, Description: "The profile hands out the role's credentials, so holding the profile gives the role's permissions.",
			From: []string{"iam:instance-profile"}, To: []string{"iam:role"}},
		{Name: "aws_task_role", Direction: schema.Forward, Confidence: schema.Extracted, Description: "Compromise of the task yields the task role credentials. Both criteria matched.",
			From: []string{"ecs:task", "ecs:service"}, To: []string{"iam:role"}},
		{Name: "aws_exec_role", Direction: schema.Forward, Confidence: schema.Extracted, Description: "The agent runs with the execution role, so compromise of the task path yields it. Both criteria matched.",
			From: []string{"ecs:task", "ecs:service"}, To: []string{"iam:role"}},
		{Name: "aws_lambda_role", Direction: schema.Forward, Confidence: schema.Extracted, Description: "Compromise of the function yields its execution role credentials. Both criteria matched.",
			From: []string{"lambda:function"}, To: []string{"iam:role"}},
		{Name: "aws_cluster_role", Direction: schema.Forward, Confidence: schema.Extracted, Description: "Compromise of the cluster or node group yields the role it runs as. Both criteria matched.",
			From: []string{"eks:cluster", "eks:nodegroup"}, To: []string{"iam:role"}},
		{Name: "aws_in_cluster", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The resource is contained in the cluster.",
			From: []string{"ecs:service", "ecs:task", "eks:nodegroup"}, To: []string{"ecs:cluster", "eks:cluster"}},
		{Name: "aws_service_of", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The task is owned by its service.",
			From: []string{"ecs:task"}, To: []string{"ecs:service"}},
		{Name: "aws_uses_layer", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The function depends on the layer code.",
			From: []string{"lambda:function"}, To: []string{"lambda:layer"}},
		{Name: "aws_uses_subnet", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The resource places its members in these subnets and depends on them.",
			From: []string{"autoscaling:group", "eks:cluster", "eks:nodegroup"}, To: []string{"ec2:subnet"}},
		{Name: "aws_in_nodegroup", Direction: schema.Reverse, Confidence: schema.Inferred, Description: "The node is a member of the group. Inferred from the node group tag, not from an API link.",
			From: []string{"ec2:instance"}, To: []string{"eks:nodegroup"}},
		{Name: "aws_member_of_group", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The user inherits the group's policies; a group change impacts the user.",
			From: []string{"iam:user"}, To: []string{"iam:group"}},
		{Name: "aws_attached_policy", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "States only that a policy is attached to an identity. It does not establish effective access; `aws_can_access` does.",
			From: []string{"iam:user", "iam:group", "iam:role"}, To: []string{"iam:policy", "iam:inline-policy"}},
		{Name: "aws_trusts", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The role's trust policy names the principal; compromise of that principal can assume the role, so impact flows to the role.",
			From: []string{"iam:role"}, To: []string{"iam:user", "iam:role", "aws_account", "iam:group"}},
		{Name: "aws_can_assume", Direction: schema.Forward, Confidence: schema.Inferred, Description: "The principal can obtain the role's credentials. Inferred because only the trust side is collected until analysis exists.",
			From: []string{"iam:user", "iam:role", "ec2:instance", "lambda:function"}, To: []string{"iam:role"}},
		{Name: "aws_can_pass_role", Direction: schema.Forward, Confidence: schema.Inferred, Description: "The principal can hand the role to a service and so act through it. Inferred from policy text.",
			From: []string{"iam:user", "iam:role"}, To: []string{"iam:role"}},
		{Name: "aws_has_boundary", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The principal's permissions depend on the boundary policy.",
			From: []string{"iam:user", "iam:role"}, To: []string{"iam:policy"}},
		{Name: "aws_statement_of", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The statement is part of its policy or trust policy.",
			From: []string{"aws_policy_statement"}, To: []string{"iam:policy", "iam:inline-policy", "iam:role"}},
		{Name: "aws_can_access", Direction: schema.Forward, Confidence: schema.Inferred, Description: "Derived by Authorization_Analysis from policies, boundaries, SCPs, and conditions. Carries Evidence and Confidence. Not produced by a collector.",
			From: []string{"iam:user", "iam:role", "iam:group"}, To: []string{"aws_resource"}, Derived: true},
		{Name: "aws_encrypted_by", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The resource depends on its key for confidentiality and availability.",
			From: []string{"aws_resource"}, To: []string{"kms:key"}},
		{Name: "aws_stores_in", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The instance keeps its data in the cluster storage.",
			From: []string{"rds:instance"}, To: []string{"rds:cluster"}},
		{Name: "aws_reads_from", Direction: schema.Forward, Confidence: schema.Inferred, Description: "Compromise of the reader gives access to the data it reads. Both criteria matched. Inferred from configuration.",
			From: []string{"lambda:function", "ecs:task", "ec2:instance"}, To: []string{"aws_resource"}},
		{Name: "aws_writes_to", Direction: schema.Forward, Confidence: schema.Inferred, Description: "Compromise of the writer lets an attacker alter the data. Inferred from configuration.",
			From: []string{"lambda:function", "ecs:task", "ec2:instance"}, To: []string{"aws_resource"}},
		{Name: "aws_attached_volume", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The instance depends on its volume. Not `attached_to`.",
			From: []string{"ec2:instance"}, To: []string{"ec2:volume"}},
		{Name: "aws_mounts_fs", Direction: schema.Forward, Confidence: schema.Extracted, Description: "Compromise of the mounting workload gives access to the file system. Both criteria matched.",
			From: []string{"ec2:instance", "ecs:task", "lambda:function"}, To: []string{"efs:file-system"}},
		{Name: "aws_snapshot_of", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The snapshot is derived from the volume.",
			From: []string{"ec2:snapshot"}, To: []string{"ec2:volume"}},
		{Name: "aws_alias_of", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The alias resolves to the key.",
			From: []string{"kms:alias"}, To: []string{"kms:key"}},
		{Name: "aws_monitors", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "Monitoring coverage depends on the monitored subject; the subject's loss impacts the monitor's view.",
			From: []string{"guardduty:detector", "config:recorder", "config:rule"}, To: []string{"aws_account", "aws_resource"}},
		{Name: "aws_logs_to", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The trail depends on the bucket as its log sink.",
			From: []string{"cloudtrail:trail"}, To: []string{"s3:bucket"}},
		{Name: "aws_protects", Direction: schema.Forward, Confidence: schema.Extracted, Description: "Failure of the web ACL removes protection from the resource, giving a fault reach over it.",
			From: []string{"wafv2:web-acl"}, To: []string{"elbv2:load-balancer", "aws_resource"}},
		{Name: "aws_finding_affects", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The finding exists because of the resource; loss of the resource impacts the finding.",
			From: []string{"guardduty:finding", "securityhub:finding", "inspector2:finding"}, To: []string{"aws_resource"}},
		{Name: "aws_record_in_zone", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The record is contained in its zone.",
			From: []string{"route53:record"}, To: []string{"route53:hosted-zone"}},
		{Name: "aws_dns_points_to", Direction: schema.Reverse, Confidence: schema.Extracted, Description: "The record depends on the resource it names, so loss of the resource breaks resolution. Used only when the target is a resource identifier.",
			From: []string{"route53:record"}, To: []string{"elbv2:load-balancer", "ec2:eip", "s3:bucket", "ec2:instance"}},
	}
}
